package org.marketreview.nativeapp;
import java.util.*;import java.util.function.BooleanSupplier;
/** Pure local historical observations. No clocks, storage, Android classes or network. */
public final class ChartAnnotations {
 public static final class Point {public Engine.Bar bar;public String date="";public double availableAt=Double.NaN,closedAt=Double.NaN;public Point(Engine.Bar b){bar=b;}}
 public static final class Context {public String source="",instrument="",period="",adjustment="unknown",volumeUnit="unknown";public double asOf=Double.NaN;}
 public static final class Touch {public int index,confirmedIndex;public String date;public double price;public boolean rejected,volumeConfirmed;Touch(int i,String d,double p,boolean r,boolean v){index=i;confirmedIndex=i+2;date=d;price=p;rejected=r;volumeConfirmed=v;}}
 public static final class Level {public boolean present;public String type="",strength="",status="";public double price=Double.NaN,distancePct=Double.NaN,tolerance=Double.NaN;public int rejectionCount,volumeConfirmedTouches;public List<Touch> touches=new ArrayList<>();}
 public static final class Validation {public String status="pending";public int bars;public double forwardClosePct=Double.NaN,maxPct=Double.NaN,minPct=Double.NaN;}
 public static final class Event {public int index;public String date,type,direction;public double price,close,threshold,volumeRatio,priceChangePct,dependenciesAvailableAt=Double.NaN;public String triggerAvailability="unproven-at-bar-close";public Validation validation=new Validation();}
 public static final class Result {public String status="unavailable",reason="";public Context context;public int selected=-1,lookbackBars;public boolean snapshotOnly=true;public double pivot=Double.NaN,r1=Double.NaN,s1=Double.NaN,r1DistancePct=Double.NaN,s1DistancePct=Double.NaN,tolerance=Double.NaN,tolerancePct=Double.NaN;public String sourceDate="";public Level support=new Level(),resistance=new Level();public List<Event> events=new ArrayList<>();public List<String> exclusions=new ArrayList<>();}
 static double fixed(double n){return LegacyIndicators.fixed(n,2);}static boolean volume(double n){return Double.isFinite(n)&&n>=0;}static void active(BooleanSupplier c){if(c!=null&&c.getAsBoolean())throw new IllegalStateException("cancelled");}
 static final class Cluster {double price;List<Touch> touches=new ArrayList<>();Cluster(double p){price=p;}}
 static Level clustered(List<Touch> points,boolean support,double close,double tolerance){List<Cluster> clusters=new ArrayList<>();points.sort(Comparator.comparingDouble(t->t.price));for(Touch p:points){Cluster found=null;for(Cluster c:clusters)if(Math.abs(c.price-p.price)<=tolerance){found=c;break;}if(found==null){found=new Cluster(p.price);clusters.add(found);}found.touches.add(p);double sum=0;for(Touch t:found.touches)sum+=t.price;found.price=sum/found.touches.size();}
  clusters.removeIf(c->support?c.price>close+tolerance:c.price<close-tolerance);clusters.sort((a,b)->{int compare=Double.compare(Math.abs(close-a.price),Math.abs(close-b.price));return compare==0?Integer.compare(b.touches.size(),a.touches.size()):compare;});Level out=new Level();if(clusters.isEmpty())return out;Cluster c=clusters.get(0);out.present=true;out.type=support?"support":"resistance";out.price=fixed(c.price);out.distancePct=fixed((out.price-close)/close*100);out.tolerance=LegacyIndicators.fixed(tolerance,4);out.touches=c.touches;for(Touch t:c.touches){if(t.rejected)out.rejectionCount++;if(t.volumeConfirmed)out.volumeConfirmedTouches++;}out.strength=c.touches.size()>=3&&out.rejectionCount>=2?"strong":c.touches.size()>=2?"moderate":"weak";out.status=Math.abs(close-out.price)<=tolerance?"testing":support?(close<out.price-tolerance?"broken-down":"holding-above"):(close>out.price+tolerance?"broken-up":"holding-below");return out;
 }
 public static Result calculate(List<Point> points,Context context,int selected,BooleanSupplier cancelled){active(cancelled);Result out=new Result();out.context=context;out.selected=selected;if(points.size()>10000){out.reason="bar-limit-10000";return out;}for(Point p:points)out.exclusions.add("");if(context.source.isEmpty()||context.instrument.isEmpty()||context.period.isEmpty()||!Double.isFinite(context.asOf)||context.asOf<0||context.asOf>253402214400000.0){out.reason="source-instrument-period-asof-required";return out;}
  double previous=Double.NEGATIVE_INFINITY;boolean[] ok=new boolean[points.size()];out.snapshotOnly=false;
  for(int i=0;i<points.size();i++){active(cancelled);Point p=points.get(i);Engine.Bar b=p.bar;if(!Double.isFinite(b.time)||b.time<0||b.time>253402214400000.0||b.time<=previous){out.reason="non-increasing-time";return out;}previous=b.time;String why="";if(!Engine.valid(b))why="data-gap";else if(!b.closed)why="unclosed-period";else if(b.time>context.asOf)why="future-time";else if((Double.isFinite(p.availableAt)&&p.availableAt<b.time)||(Double.isFinite(p.closedAt)&&p.closedAt<b.time))why="invalid-evidence-time";else if(Double.isFinite(p.availableAt)&&p.availableAt>context.asOf)why="future-availability";else if(Double.isFinite(p.closedAt)&&p.closedAt>context.asOf)why="future-close";if(!Double.isFinite(p.availableAt))out.snapshotOnly=true;out.exclusions.set(i,why);ok[i]=why.isEmpty();}
  if(selected<0||selected>=points.size()){out.reason="select-a-bar";return out;}if(!ok[selected]){out.reason=out.exclusions.get(selected);return out;}out.status="available";Engine.Bar last=points.get(selected).bar;int begin=selected;while(begin>0&&ok[begin-1])--begin;
  if(selected-begin>=1){Point prev=points.get(selected-1);double pivot=(prev.bar.high+prev.bar.low+prev.bar.close)/3;out.pivot=fixed(pivot);out.r1=fixed(2*pivot-prev.bar.low);out.s1=fixed(2*pivot-prev.bar.high);out.r1DistancePct=fixed((2*pivot-prev.bar.low-last.close)/last.close*100);out.s1DistancePct=fixed((2*pivot-prev.bar.high-last.close)/last.close*100);out.sourceDate=prev.date;}
  int start=Math.max(begin,selected-120);out.lookbackBars=selected-start;
  if(out.lookbackBars>=10){double sum=0;int trStart=Math.max(start,selected-14);for(int i=trStart;i<selected;i++){Engine.Bar b=points.get(i).bar;double range=b.high-b.low;if(i>start)range=Math.max(range,Math.max(Math.abs(b.high-points.get(i-1).bar.close),Math.abs(b.low-points.get(i-1).bar.close)));sum+=range;}double tolerance=Math.max(last.close*.005,sum/(selected-trStart)*.35);out.tolerance=LegacyIndicators.fixed(tolerance,4);out.tolerancePct=LegacyIndicators.fixed(tolerance/last.close*100,3);List<Touch> lows=new ArrayList<>(),highs=new ArrayList<>();
   for(int i=start+2;i<selected-2;i++){active(cancelled);Engine.Bar b=points.get(i).bar;boolean low=true,high=true;for(int j=i-2;j<=i+2;j++)if(j!=i){low=low&&b.low<points.get(j).bar.low;high=high&&b.high>points.get(j).bar.high;}double volumeSum=0;int volumes=0;for(int j=Math.max(start,i-20);j<i;j++)if(volume(points.get(j).bar.volume)){volumeSum+=points.get(j).bar.volume;volumes++;}boolean confirmed=volumes>=5&&volumeSum>0&&volume(b.volume)&&b.volume>=volumeSum/volumes*1.2;if(low)lows.add(new Touch(i,points.get(i).date,b.low,b.close>=b.low+(b.high-b.low)*.5,confirmed));if(high)highs.add(new Touch(i,points.get(i).date,b.high,b.close<=b.high-(b.high-b.low)*.5,confirmed));
   }out.support=clustered(lows,true,last.close,tolerance);out.resistance=clustered(highs,false,last.close,tolerance);
  }
  int consecutive=0;for(int i=0;i<=selected;i++){active(cancelled);consecutive=ok[i]?consecutive+1:0;if(consecutive<21)continue;Engine.Bar b=points.get(i).bar,prev=points.get(i-1).bar;double high=Double.NEGATIVE_INFINITY,low=Double.POSITIVE_INFINITY,total=0;boolean allVolumes=true;for(int j=i-20;j<i;j++){Engine.Bar bar=points.get(j).bar;high=Math.max(high,bar.high);low=Math.min(low,bar.low);allVolumes=allVolumes&&volume(bar.volume);total+=bar.volume;}double ratio=allVolumes&&total>0&&volume(b.volume)?b.volume/(total/20):Double.NaN,change=(b.close-prev.close)/prev.close*100;Event e=new Event();e.index=i;e.date=points.get(i).date;e.close=fixed(b.close);e.volumeRatio=fixed(ratio);e.priceChangePct=fixed(change);
   if(b.close>high){e.type="breakout-up";e.direction="positive";e.threshold=high;}else if(b.close<low){e.type="breakout-down";e.direction="negative";e.threshold=low;}else if(b.low>prev.high){e.type="gap-up";e.direction="positive";e.threshold=prev.high;}else if(b.high<prev.low){e.type="gap-down";e.direction="negative";e.threshold=prev.low;}else if(Double.isFinite(ratio)&&ratio>=1.8&&Math.abs(change)>=1){e.type=change>=0?"volume-expansion-up":"volume-expansion-down";e.direction=change>=0?"positive":"negative";e.threshold=total/20;}else continue;
   boolean allAvailable=true;double available=0;for(int j=i-20;j<=i;j++){allAvailable=allAvailable&&Double.isFinite(points.get(j).availableAt);if(Double.isFinite(points.get(j).availableAt))available=Math.max(available,points.get(j).availableAt);}if(allAvailable){e.dependenciesAvailableAt=available;if(Double.isFinite(points.get(i).closedAt))e.triggerAvailability=available<=points.get(i).closedAt?"declared-available-by-bar-close":"later-available-reconstruction";}
   e.price=e.direction.equals("positive")?b.low:b.high;e.threshold=fixed(e.threshold);double max=Double.NEGATIVE_INFINITY,min=Double.POSITIVE_INFINITY;int lastFuture=i;for(int j=i+1;j<points.size()&&j<=i+5&&ok[j];j++){active(cancelled);e.validation.bars++;lastFuture=j;max=Math.max(max,points.get(j).bar.high);min=Math.min(min,points.get(j).bar.low);}if(e.validation.bars>0){e.validation.status=e.validation.bars==5?"available":"partial";e.validation.forwardClosePct=fixed((points.get(lastFuture).bar.close-b.close)/b.close*100);e.validation.maxPct=fixed((max-b.close)/b.close*100);e.validation.minPct=fixed((min-b.close)/b.close*100);}out.events.add(e);
  }if(out.events.size()>16)out.events=new ArrayList<>(out.events.subList(out.events.size()-16,out.events.size()));return out;
 }
}
